import React, { useState, useEffect, useMemo } from "react";
import { Scissors, Calendar, Repeat, Clock, Check, ChevronRight, ChevronLeft, User, X, AlertCircle } from "lucide-react";
import { db } from "./firebase.js";
import { collection, doc, onSnapshot, runTransaction, serverTimestamp } from "firebase/firestore";

const SETTINGS_REF = ["settings", "geral"];

/* ------------------------------------------------------------------
   AGBAREARIA — token system
   Cor:
     ink        #14100D  fundo principal (preto quente)
     ink2       #1D1712  fundo elevado (cards)
     line       #2E2620  bordas/hairlines
     bone       #F2EAD8  texto principal
     steel      #9B9285  texto secundário
     gold       #C9962C  acento primário
     goldBright #E6B85C  acento hover
     blade      #A23B2E  acento de alerta / esporádico
   Tipografia:
     display -> 'Bebas Neue' (cartaz de barbearia, condensada)
     body    -> 'Work Sans'
     mono    -> 'JetBrains Mono' (preços, horários)
   Assinatura: "corte de lâmina" — linha diagonal serrilhada que separa
   as seções, como um talho de navalha sobre o papel.
------------------------------------------------------------------- */

const LOGO_DATA_URI =
  "data:image/jpeg;base64,";

const FONT_LINK_ID = "agb-fonts";
function useFonts() {
  useEffect(() => {
    if (document.getElementById(FONT_LINK_ID)) return;
    const link = document.createElement("link");
    link.id = FONT_LINK_ID;
    link.rel = "stylesheet";
    link.href =
      "https://fonts.googleapis.com/css2?family=Bebas+Neue&family=Work+Sans:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500;700&display=swap";
    document.head.appendChild(link);
  }, []);
}

const DEFAULT_SERVICES = [
  { id: "corte", name: "Corte", price: 40, note: null },
  { id: "barba", name: "Corte + Barba", price: 60, note: null },
  { id: "sobrancelha", name: "Corte + Sobrancelha", price: 45, note: null },
  { id: "milagroso", name: "Corte Milagroso", price: 60, note: null },
  { id: "pezinho", name: "Pezinho", price: 10, note: null },
  { id: "penteado", name: "Penteado", price: 30, note: null },
  { id: "luzes", name: "Corte + Luzes", price: 70, note: null },
  { id: "desenho", name: "Desenho Detalhado", price: 10, note: "a partir de, pode variar" },
];

const WEEKDAYS = ["Domingo", "Segunda", "Terça", "Quarta", "Quinta", "Sexta", "Sábado"];
const WEEKDAYS_SHORT = ["Dom", "Seg", "Ter", "Qua", "Qui", "Sex", "Sáb"];
const TIME_SLOTS = ["09:00", "10:00", "11:00", "13:00", "14:00", "15:00", "16:00", "17:00", "18:00", "19:00"];

function fmtPrice(v) {
  return v.toLocaleString("pt-BR", { minimumFractionDigits: 2, maximumFractionDigits: 2 });
}

function nextDates(days = 21) {
  const out = [];
  const today = new Date();
  today.setHours(0, 0, 0, 0);
  for (let i = 0; i < days; i++) {
    const d = new Date(today);
    d.setDate(d.getDate() + i);
    if (d.getDay() === 0) continue; // barbearia fechada domingo
    out.push(d);
  }
  return out;
}

function dateKey(d) {
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;
}

/* Armazenamento dos agendamentos no Firestore (coleção "bookings").
   O id de cada documento é a própria chave do horário (ex: "esp:2026-08-13:09:00"),
   o que permite usar uma transação para reservar um horário só se ele ainda
   não existir — evita dois clientes marcando o mesmo horário ao mesmo tempo. */
const BOOKINGS_COLLECTION = "bookings";

/* Divisor "corte de lâmina": SVG diagonal serrilhado */
function BladeCut({ flip }) {
  return (
    <div className={`w-full h-6 overflow-hidden ${flip ? "rotate-180" : ""}`} aria-hidden="true">
      <svg viewBox="0 0 400 24" preserveAspectRatio="none" className="w-full h-full">
        <polyline
          points="0,0 20,20 40,2 60,22 80,0 100,20 120,2 140,22 160,0 180,20 200,2 220,22 240,0 260,20 280,2 300,22 320,0 340,20 360,2 380,22 400,0"
          fill="none"
          stroke="#C9962C"
          strokeWidth="1.5"
        />
      </svg>
    </div>
  );
}

function StepDot({ active, done, label, index }) {
  return (
    <div className="flex items-center gap-2">
      <div
        className={`w-7 h-7 rounded-full flex items-center justify-center text-xs font-bold border transition-colors
        ${done ? "bg-[#C9962C] border-[#C9962C] text-[#14100D]" : active ? "border-[#C9962C] text-[#C9962C]" : "border-[#3A322A] text-[#6b6459]"}`}
      >
        {done ? <Check size={14} /> : index}
      </div>
      <span className={`text-xs uppercase tracking-wide hidden sm:inline ${active || done ? "text-[#F2EAD8]" : "text-[#6b6459]"}`}>
        {label}
      </span>
    </div>
  );
}

export default function AGBarbearia() {
  useFonts();

  const [step, setStep] = useState(1);
  const [service, setService] = useState(null);
  const [mode, setMode] = useState(null); // 'esporadico' | 'fixo'
  const [selectedDate, setSelectedDate] = useState(null); // Date obj (esporadico)
  const [selectedWeekday, setSelectedWeekday] = useState(null); // 0-6 (fixo)
  const [selectedTime, setSelectedTime] = useState(null);
  const [clientName, setClientName] = useState("");
  const [clientPhone, setClientPhone] = useState("");

  const [bookings, setBookings] = useState({ esporadico: {}, fixo: {} }); // key -> {name, service}
  const [loadingSlots, setLoadingSlots] = useState(true);
  const [confirmed, setConfirmed] = useState(null);
  const [error, setError] = useState("");

  const [services, setServices] = useState(DEFAULT_SERVICES);
  const [agendaAberta, setAgendaAberta] = useState(true);

  const dates = useMemo(() => nextDates(21), []);

  useEffect(() => {
    const unsub = onSnapshot(doc(db, ...SETTINGS_REF), (snap) => {
      const data = snap.data();
      if (data) {
        if (data.services?.length) setServices(data.services);
        setAgendaAberta(data.agendaAberta !== false);
      }
    });
    return () => unsub();
  }, []);

  useEffect(() => {
    const unsub = onSnapshot(
      collection(db, BOOKINGS_COLLECTION),
      (snap) => {
        const esp = {};
        const fix = {};
        snap.forEach((d) => {
          if (d.id.startsWith("esp:")) esp[d.id] = d.data();
          else if (d.id.startsWith("fix:")) fix[d.id] = d.data();
        });
        setBookings({ esporadico: esp, fixo: fix });
        setLoadingSlots(false);
      },
      () => {
        // sem conexão — segue com agenda vazia em memória
        setLoadingSlots(false);
      }
    );
    return () => unsub();
  }, []);

  const goTo = (n) => {
    setError("");
    setStep(n);
  };

  const canNextFromStep1 = !!service;
  const canNextFromStep2 = !!mode;
  const canNextFromStep3 =
    mode === "esporadico" ? !!selectedDate && !!selectedTime : mode === "fixo" ? selectedWeekday !== null && !!selectedTime : false;

  const isSlotTaken = (t) => {
    if (mode === "esporadico" && selectedDate) {
      const key = `esp:${dateKey(selectedDate)}:${t}`;
      if (bookings.esporadico[key]) return true;
      // também bloqueia se existir horário fixo cadastrado pro mesmo dia da semana
      const wd = selectedDate.getDay();
      const fixKey = `fix:${wd}:${t}`;
      if (bookings.fixo[fixKey]) return true;
      return false;
    }
    if (mode === "fixo" && selectedWeekday !== null) {
      const key = `fix:${selectedWeekday}:${t}`;
      return !!bookings.fixo[key];
    }
    return false;
  };

  const handleConfirm = async () => {
    if (!clientName.trim()) {
      setError("Informe seu nome para confirmar.");
      return;
    }
    setError("");
    const payload = {
      name: clientName.trim(),
      phone: clientPhone.trim(),
      service: service.name,
      price: service.price,
      mode,
      createdAt: serverTimestamp(),
    };
    const key =
      mode === "esporadico" ? `esp:${dateKey(selectedDate)}:${selectedTime}` : `fix:${selectedWeekday}:${selectedTime}`;
    try {
      await runTransaction(db, async (tx) => {
        const ref = doc(db, BOOKINGS_COLLECTION, key);
        const snap = await tx.get(ref);
        if (snap.exists()) {
          throw new Error("SLOT_TAKEN");
        }
        tx.set(ref, payload);
      });
      setConfirmed({
        mode,
        service: service.name,
        price: service.price,
        time: selectedTime,
        date: mode === "esporadico" ? selectedDate : null,
        weekday: mode === "fixo" ? selectedWeekday : null,
        name: clientName.trim(),
      });
      setStep(5);
    } catch (e) {
      if (e.message === "SLOT_TAKEN") {
        setError(mode === "esporadico" ? "Esse horário acabou de ser reservado. Escolha outro." : "Esse horário fixo já está ocupado. Escolha outro.");
      } else {
        setError("Não foi possível confirmar agora. Verifique sua internet e tente novamente.");
      }
    }
  };

  const resetFlow = () => {
    setStep(1);
    setService(null);
    setMode(null);
    setSelectedDate(null);
    setSelectedWeekday(null);
    setSelectedTime(null);
    setClientName("");
    setClientPhone("");
    setConfirmed(null);
    setError("");
  };

  return (
    <div
      className="min-h-screen w-full"
      style={{ background: "#14100D", fontFamily: "'Work Sans', sans-serif", color: "#F2EAD8" }}
    >
      <style>{`
        .font-display { font-family: 'Bebas Neue', sans-serif; letter-spacing: 0.03em; }
        .font-mono { font-family: 'JetBrains Mono', monospace; }
        ::selection { background: #C9962C; color: #14100D; }
      `}</style>

      {/* Header */}
      <header className="border-b border-[#2E2620] sticky top-0 z-30 backdrop-blur" style={{ background: "rgba(20,16,13,0.92)" }}>
        <div className="max-w-5xl mx-auto px-5 py-4 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <Scissors size={20} className="text-[#C9962C]" />
            <span className="font-display text-2xl tracking-wider">AGBARBEARIA</span>
          </div>
          <span className="text-[11px] uppercase tracking-[0.2em] text-[#9B9285] hidden sm:block">Terça a Sábado</span>
        </div>
      </header>

      {/* Hero */}
      <section className="max-w-5xl mx-auto px-5 pt-14 pb-8">
        <p className="font-mono text-xs uppercase tracking-[0.3em] text-[#C9962C] mb-3">Agendamento online</p>
        <img
          src={LOGO_DATA_URI}
          alt="AGBARBEARIA"
          className="w-full max-w-xl rounded-md border border-[#2E2620] mb-4"
        />
        <p className="text-[#9B9285] max-w-md text-sm sm:text-base">
          Escolha entre um horário esporádico, pra essa semana, ou fixe seu dia e hora toda semana com a AGBARBEARIA.
        </p>
      </section>

      <BladeCut />

      {/* Menu de serviços */}
      <section id="servicos" className="max-w-5xl mx-auto px-5 py-10">
        <h2 className="font-display text-3xl text-[#C9962C] mb-6">TABELA DE PREÇOS</h2>
        <div className="border-t border-[#2E2620]">
          {services.map((s) => (
            <div key={s.id} className="flex items-baseline justify-between py-3 border-b border-[#2E2620] group">
              <div className="flex items-baseline gap-2 min-w-0">
                <span className="text-[15px] sm:text-base">{s.name}</span>
                {s.note && <span className="text-[11px] text-[#6b6459] italic whitespace-nowrap">{s.note}</span>}
              </div>
              <div className="flex-1 mx-3 border-b border-dotted border-[#3A322A] translate-y-[-4px]" />
              <span className="font-mono text-[#F2EAD8] whitespace-nowrap">
                R$ {s.note ? "a partir de " : ""}
                {fmtPrice(s.price)}
              </span>
            </div>
          ))}
        </div>
      </section>

      <BladeCut flip />

      {/* Fluxo de agendamento */}
      <section id="agendar" className="max-w-3xl mx-auto px-5 py-12">
        <h2 className="font-display text-3xl text-[#C9962C] mb-2">MARCAR HORÁRIO</h2>

        {!agendaAberta ? (
          <div className="border border-[#2E2620] rounded-md bg-[#171310] p-6 text-center">
            <p className="font-medium mb-1">Agenda fechada no momento</p>
            <p className="text-[#9B9285] text-sm">Não estamos aceitando novos agendamentos agora. Volte mais tarde.</p>
          </div>
        ) : (
          <>
        <p className="text-[#9B9285] text-sm mb-8">Siga os passos abaixo para reservar seu horário.</p>

        {step <= 4 && (
          <div className="flex items-center gap-4 sm:gap-6 mb-10 overflow-x-auto pb-1">
            <StepDot index={1} label="Serviço" active={step === 1} done={step > 1} />
            <ChevronRight size={14} className="text-[#3A322A] shrink-0" />
            <StepDot index={2} label="Tipo" active={step === 2} done={step > 2} />
            <ChevronRight size={14} className="text-[#3A322A] shrink-0" />
            <StepDot index={3} label="Data/Hora" active={step === 3} done={step > 3} />
            <ChevronRight size={14} className="text-[#3A322A] shrink-0" />
            <StepDot index={4} label="Confirmar" active={step === 4} done={step > 4} />
          </div>
        )}

        {/* STEP 1 — serviço */}
        {step === 1 && (
          <div>
            <div className="grid sm:grid-cols-2 gap-3 mb-8">
              {services.map((s) => (
                <button
                  key={s.id}
                  onClick={() => setService(s)}
                  className={`text-left p-4 rounded-md border transition-colors focus:outline-none focus-visible:ring-2 focus-visible:ring-[#C9962C]
                  ${service?.id === s.id ? "border-[#C9962C] bg-[#1D1712]" : "border-[#2E2620] hover:border-[#4a4034] bg-[#171310]"}`}
                >
                  <div className="flex items-center justify-between">
                    <span className="font-medium">{s.name}</span>
                    <span className="font-mono text-[#C9962C] text-sm">
                      {s.note ? "a partir de " : ""}R$ {fmtPrice(s.price)}
                    </span>
                  </div>
                  {s.note && <span className="text-[11px] text-[#6b6459] italic">{s.note}</span>}
                </button>
              ))}
            </div>
            <div className="flex justify-end">
              <button
                disabled={!canNextFromStep1}
                onClick={() => goTo(2)}
                className="inline-flex items-center gap-2 px-6 py-3 rounded-md font-medium bg-[#C9962C] text-[#14100D] disabled:opacity-30 disabled:cursor-not-allowed hover:bg-[#E6B85C] transition-colors"
              >
                Continuar <ChevronRight size={16} />
              </button>
            </div>
          </div>
        )}

        {/* STEP 2 — tipo */}
        {step === 2 && (
          <div>
            <div className="grid sm:grid-cols-2 gap-4 mb-8">
              <button
                onClick={() => setMode("esporadico")}
                className={`text-left p-5 rounded-md border transition-colors ${
                  mode === "esporadico" ? "border-[#C9962C] bg-[#1D1712]" : "border-[#2E2620] hover:border-[#4a4034] bg-[#171310]"
                }`}
              >
                <Calendar size={20} className="text-[#C9962C] mb-3" />
                <p className="font-display text-xl mb-1">HORÁRIO ESPORÁDICO</p>
                <p className="text-[#9B9285] text-sm">Escolha uma data específica, só dessa vez.</p>
              </button>
              <button
                onClick={() => setMode("fixo")}
                className={`text-left p-5 rounded-md border transition-colors ${
                  mode === "fixo" ? "border-[#A23B2E] bg-[#1D1712]" : "border-[#2E2620] hover:border-[#4a4034] bg-[#171310]"
                }`}
              >
                <Repeat size={20} className="text-[#A23B2E] mb-3" />
                <p className="font-display text-xl mb-1">HORÁRIO FIXO</p>
                <p className="text-[#9B9285] text-sm">Reserve o mesmo dia da semana e horário, toda semana.</p>
              </button>
            </div>
            <div className="flex justify-between">
              <button onClick={() => goTo(1)} className="inline-flex items-center gap-2 px-5 py-3 rounded-md text-[#9B9285] hover:text-[#F2EAD8] transition-colors">
                <ChevronLeft size={16} /> Voltar
              </button>
              <button
                disabled={!canNextFromStep2}
                onClick={() => goTo(3)}
                className="inline-flex items-center gap-2 px-6 py-3 rounded-md font-medium bg-[#C9962C] text-[#14100D] disabled:opacity-30 disabled:cursor-not-allowed hover:bg-[#E6B85C] transition-colors"
              >
                Continuar <ChevronRight size={16} />
              </button>
            </div>
          </div>
        )}

        {/* STEP 3 — data/hora */}
        {step === 3 && (
          <div>
            {mode === "esporadico" ? (
              <div className="mb-6">
                <p className="text-xs uppercase tracking-wide text-[#9B9285] mb-3">Escolha o dia</p>
                <div className="flex gap-2 overflow-x-auto pb-2 mb-2">
                  {dates.map((d) => {
                    const active = selectedDate && dateKey(d) === dateKey(selectedDate);
                    return (
                      <button
                        key={dateKey(d)}
                        onClick={() => {
                          setSelectedDate(d);
                          setSelectedTime(null);
                        }}
                        className={`shrink-0 w-16 py-2 rounded-md border text-center transition-colors ${
                          active ? "border-[#C9962C] bg-[#1D1712]" : "border-[#2E2620] hover:border-[#4a4034]"
                        }`}
                      >
                        <div className="text-[10px] uppercase text-[#6b6459]">{WEEKDAYS_SHORT[d.getDay()]}</div>
                        <div className="font-mono text-lg">{d.getDate()}</div>
                      </button>
                    );
                  })}
                </div>
              </div>
            ) : (
              <div className="mb-6">
                <p className="text-xs uppercase tracking-wide text-[#9B9285] mb-3">Escolha o dia da semana</p>
                <div className="flex gap-2 flex-wrap mb-2">
                  {WEEKDAYS.map((w, i) => {
                    if (i === 0) return null; // fechado domingo
                    const active = selectedWeekday === i;
                    return (
                      <button
                        key={w}
                        onClick={() => {
                          setSelectedWeekday(i);
                          setSelectedTime(null);
                        }}
                        className={`px-4 py-2 rounded-md border text-sm transition-colors ${
                          active ? "border-[#A23B2E] bg-[#1D1712]" : "border-[#2E2620] hover:border-[#4a4034]"
                        }`}
                      >
                        {w}
                      </button>
                    );
                  })}
                </div>
              </div>
            )}

            {((mode === "esporadico" && selectedDate) || (mode === "fixo" && selectedWeekday !== null)) && (
              <div className="mb-8">
                <p className="text-xs uppercase tracking-wide text-[#9B9285] mb-3">Escolha o horário</p>
                {loadingSlots ? (
                  <p className="text-sm text-[#6b6459]">Carregando horários…</p>
                ) : (
                  <div className="grid grid-cols-4 sm:grid-cols-5 gap-2">
                    {TIME_SLOTS.map((t) => {
                      const taken = isSlotTaken(t);
                      const active = selectedTime === t;
                      return (
                        <button
                          key={t}
                          disabled={taken}
                          onClick={() => setSelectedTime(t)}
                          className={`font-mono py-2 rounded-md border text-sm transition-colors
                          ${taken ? "border-[#2E2620] text-[#4a4034] cursor-not-allowed line-through" : active ? "border-[#C9962C] bg-[#1D1712] text-[#F2EAD8]" : "border-[#2E2620] hover:border-[#4a4034]"}`}
                        >
                          {t}
                        </button>
                      );
                    })}
                  </div>
                )}
              </div>
            )}

            <div className="flex justify-between">
              <button onClick={() => goTo(2)} className="inline-flex items-center gap-2 px-5 py-3 rounded-md text-[#9B9285] hover:text-[#F2EAD8] transition-colors">
                <ChevronLeft size={16} /> Voltar
              </button>
              <button
                disabled={!canNextFromStep3}
                onClick={() => goTo(4)}
                className="inline-flex items-center gap-2 px-6 py-3 rounded-md font-medium bg-[#C9962C] text-[#14100D] disabled:opacity-30 disabled:cursor-not-allowed hover:bg-[#E6B85C] transition-colors"
              >
                Continuar <ChevronRight size={16} />
              </button>
            </div>
          </div>
        )}

        {/* STEP 4 — confirmar */}
        {step === 4 && (
          <div>
            <div className="rounded-md border border-[#2E2620] bg-[#171310] p-5 mb-6">
              <div className="flex items-center gap-2 mb-4 text-[#C9962C]">
                {mode === "esporadico" ? <Calendar size={16} /> : <Repeat size={16} />}
                <span className="text-xs uppercase tracking-wide">
                  {mode === "esporadico" ? "Horário esporádico" : "Horário fixo semanal"}
                </span>
              </div>
              <p className="mb-1">
                <span className="text-[#9B9285]">Serviço: </span>
                {service?.name} — <span className="font-mono">R$ {fmtPrice(service?.price)}</span>
              </p>
              <p className="mb-1">
                <span className="text-[#9B9285]">Quando: </span>
                {mode === "esporadico"
                  ? `${WEEKDAYS[selectedDate.getDay()]}, ${selectedDate.getDate()}/${selectedDate.getMonth() + 1}`
                  : `Toda ${WEEKDAYS[selectedWeekday]}`}{" "}
                às <span className="font-mono">{selectedTime}</span>
              </p>
            </div>

            <div className="space-y-3 mb-6">
              <div>
                <label className="text-xs uppercase tracking-wide text-[#9B9285] block mb-1">Seu nome</label>
                <input
                  value={clientName}
                  onChange={(e) => setClientName(e.target.value)}
                  placeholder="Nome completo"
                  className="w-full bg-[#171310] border border-[#2E2620] rounded-md px-3 py-2.5 text-sm focus:outline-none focus:border-[#C9962C]"
                />
              </div>
              <div>
                <label className="text-xs uppercase tracking-wide text-[#9B9285] block mb-1">WhatsApp (opcional)</label>
                <input
                  value={clientPhone}
                  onChange={(e) => setClientPhone(e.target.value)}
                  placeholder="(00) 00000-0000"
                  className="w-full bg-[#171310] border border-[#2E2620] rounded-md px-3 py-2.5 text-sm focus:outline-none focus:border-[#C9962C]"
                />
              </div>
            </div>

            {error && (
              <div className="flex items-start gap-2 text-[#E6897B] text-sm mb-4">
                <AlertCircle size={16} className="mt-0.5 shrink-0" />
                <span>{error}</span>
              </div>
            )}

            <div className="flex justify-between">
              <button onClick={() => goTo(3)} className="inline-flex items-center gap-2 px-5 py-3 rounded-md text-[#9B9285] hover:text-[#F2EAD8] transition-colors">
                <ChevronLeft size={16} /> Voltar
              </button>
              <button
                onClick={handleConfirm}
                className="inline-flex items-center gap-2 px-6 py-3 rounded-md font-medium bg-[#C9962C] text-[#14100D] hover:bg-[#E6B85C] transition-colors"
              >
                Confirmar agendamento <Check size={16} />
              </button>
            </div>
          </div>
        )}

        {/* STEP 5 — sucesso */}
        {step === 5 && confirmed && (
          <div className="text-center py-6">
            <div className="w-14 h-14 rounded-full bg-[#C9962C] text-[#14100D] flex items-center justify-center mx-auto mb-5">
              <Check size={26} />
            </div>
            <h3 className="font-display text-3xl mb-2">HORÁRIO RESERVADO</h3>
            <p className="text-[#9B9285] mb-6 text-sm">
              {confirmed.name}, seu {confirmed.service.toLowerCase()} está marcado{" "}
              {confirmed.mode === "esporadico"
                ? `para ${WEEKDAYS[confirmed.date.getDay()]}, ${confirmed.date.getDate()}/${confirmed.date.getMonth() + 1}`
                : `toda ${WEEKDAYS[confirmed.weekday]}`}{" "}
              às <span className="font-mono text-[#F2EAD8]">{confirmed.time}</span>.
            </p>
            <button
              onClick={resetFlow}
              className="inline-flex items-center gap-2 px-6 py-3 rounded-md font-medium border border-[#C9962C] text-[#C9962C] hover:bg-[#1D1712] transition-colors"
            >
              Marcar outro horário
            </button>
          </div>
        )}
          </>
        )}
      </section>

      <BladeCut />

      <footer className="max-w-5xl mx-auto px-5 py-8 flex items-center justify-between text-[11px] text-[#6b6459] uppercase tracking-wide">
        <span>AGBARBEARIA</span>
        <span className="flex items-center gap-1">
          <User size={12} /> Agenda sincronizada em tempo real
        </span>
      </footer>
    </div>
  );
}
